package subtitle

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"maps"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
)

// fixTextGolden is testdata/fixtext/golden.json: what ftfy, as Bazarr
// vendors it, makes of texts and the tables it builds, generated by
// golden.py.
type fixTextGolden struct {
	Cases []struct {
		Name         string `json:"name"`
		Input        string `json:"input"`
		InputWTF8Hex string `json:"input_wtf8_hex"`
		Repeat       *struct {
			Prefix string `json:"prefix"`
			Unit   string `json:"unit"`
			Count  int    `json:"count"`
		} `json:"repeat"`
		Output       string `json:"output"`
		OutputSHA256 string `json:"output_sha256"`
	} `json:"cases"`
	Tables struct {
		HTMLEntities       map[string]string `json:"html_entities"`
		Codecs             map[string][]rune `json:"codecs"`
		MojibakeCategories map[string]string `json:"mojibake_categories"`
		UTF8Clues          map[string]string `json:"utf8_clues"`
	} `json:"tables"`
}

func loadFixTextGolden(t *testing.T) fixTextGolden {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "fixtext", "golden.json"))
	if err != nil {
		t.Fatal(err)
	}
	var g fixTextGolden
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatal(err)
	}
	return g
}

func TestFixTextGolden(t *testing.T) {
	g := loadFixTextGolden(t)
	if len(g.Cases) < 40 {
		t.Fatalf("golden.json has %d cases, want at least 40", len(g.Cases))
	}
	for _, c := range g.Cases {
		t.Run(c.Name, func(t *testing.T) {
			input := c.Input
			switch {
			case c.InputWTF8Hex != "":
				b, err := hex.DecodeString(c.InputWTF8Hex)
				if err != nil {
					t.Fatal(err)
				}
				input = string(b)
			case c.Repeat != nil:
				input = c.Repeat.Prefix + strings.Repeat(c.Repeat.Unit, c.Repeat.Count)
			}
			got := FixText(input)
			if c.OutputSHA256 != "" {
				sum := sha256.Sum256([]byte(got))
				if h := hex.EncodeToString(sum[:]); h != c.OutputSHA256 {
					t.Errorf("FixText(%d characters): sha256 got = %s, want = %s", len([]rune(input)), h, c.OutputSHA256)
				}
				return
			}
			if got != c.Output {
				t.Errorf("FixText(%q)\n got = %q\nwant = %q", input, got, c.Output)
			}
		})
	}
}

// TestFixTextTables compares the tables built from data/ftfy.json with
// those ftfy builds at import time.
func TestFixTextTables(t *testing.T) {
	g := loadFixTextGolden(t).Tables
	f := getTextFixer()
	d := loadData[ftfyData]("ftfy.json")

	if !maps.Equal(f.htmlEntities, g.HTMLEntities) {
		for k, want := range g.HTMLEntities {
			if got, ok := f.htmlEntities[k]; !ok || got != want {
				t.Errorf("HTML_ENTITIES[%q] got = %q, want = %q", k, got, want)
			}
		}
		for k := range f.htmlEntities {
			if _, ok := g.HTMLEntities[k]; !ok {
				t.Errorf("HTML_ENTITIES[%q] got = %q, want none", k, f.htmlEntities[k])
			}
		}
	}
	if !maps.Equal(d.MojibakeCategories, g.MojibakeCategories) {
		t.Errorf("MOJIBAKE_CATEGORIES got = %q, want = %q", d.MojibakeCategories, g.MojibakeCategories)
	}
	if !maps.Equal(d.UTF8Clues, g.UTF8Clues) {
		t.Errorf("UTF8_CLUES got = %q, want = %q", d.UTF8Clues, g.UTF8Clues)
	}

	codecs := map[string]*byteCodec{"windows-1252": f.windows1252}
	for _, c := range f.charmaps {
		codecs[c.name] = c
	}
	if got, want := slices.Sorted(maps.Keys(codecs)), slices.Sorted(maps.Keys(g.Codecs)); !slices.Equal(got, want) {
		t.Fatalf("codecs got = %q, want = %q", got, want)
	}
	for name, want := range g.Codecs {
		if got := codecs[name].decode[:]; !slices.Equal(got, want) {
			t.Errorf("decoding table of %s got = %U, want = %U", name, got, want)
		}
	}
}

func TestDecodeWTF8(t *testing.T) {
	tests := []struct {
		in   string
		want []rune
	}{
		{"a\xed\xa0\xbdb", []rune{'a', 0xD83D, 'b'}},
		{"\xed\x9f\xbf", []rune{0xD7FF}},
		{"\xed\xa0", []rune{0xFFFD, 0xFFFD}},
		{"\xff\xc3", []rune{0xFFFD, 0xFFFD}},
		{"é", []rune{'é'}},
	}
	for _, tt := range tests {
		if got := decodeWTF8(tt.in); !slices.Equal(got, tt.want) {
			t.Errorf("decodeWTF8(%q) got = %U, want = %U", tt.in, got, tt.want)
		}
	}
}

func TestDecodeUTF8Variants(t *testing.T) {
	tests := []struct {
		in   string
		want string
		ok   bool
	}{
		{"plain é", "plain é", true},
		{"\xed\xa0\xbd\xed\xb8\x8d", "😍", true},
		{"nul\xc0\x80", "nul\x00", true},
		{"nul\xc0\n", "nul\x00", true},
		{"nul\xc0", "", false},
		{"\xc0\x41", "", false},
		{"\xed\xa0\xbd", "", false},
		{"\xed\xa0\xbd\xed\xb8\x8dx\xed", "", false},
		{"\xed\x9f\xbf", "퟿", true},
		{"\xff", "", false},
	}
	for _, tt := range tests {
		got, ok := decodeUTF8Variants([]byte(tt.in))
		if ok != tt.ok || string(got) != tt.want {
			t.Errorf("decodeUTF8Variants(%q) got = %q, %t, want = %q, %t", tt.in, string(got), ok, tt.want, tt.ok)
		}
	}
}
